 source=Path(__file__).resolve().parents[1];server=source.parent/'server/GameServer';game=install/'new-client/godot/game';native=source/'UnrealPlugin/DAoCVisualBridge/Source/DAoCVisualBridge';paths=[game/'player.gd',game/'zone_loader.gd',game/'sky_system.gd',server/'packets/Client/168/PlayerPositionUpdateHandler.cs',server/'packets/Client/168/PlayerHeadingUpdateHandler.cs',native/'Private/DAoCBridgeKeyConfiguration.cpp',native/'Private/DAoCBridgeSubsystem.cpp',native/'Private/DAoCBridgeWorldClock.inl',source/'Godot/live_gateway.gd',source/'Godot/decoded_world_adapter.gd'];assert all(p.is_file() for p in paths);inputs={str(p):digest(p) for p in paths}
