 assert all(checks.values()),checks
 result=dict(passed=True,audit_only=True,installed=False,checks=checks,source_inputs=inputs,normal_runtime_modified=False,normal_database_modified=False,world_map_modified=False,plan={'input':'Editable Shift+T proposed; preserve Training T and existing saved bindings.','persistence':'Reuse merge-preserving controls preferences; true default; clear light with world/lobby lifecycle.','light':'One bounded white personal source,3.2m above original body origin,30m range,no shadows; Unreal photometry requires actual visual verification, not copying Godot energy3.','daylight':'Reuse original night/dawn/dusk/storm weighting where available; server clock alone does not certify weather parity. Do not modify building lights or world sky.','protocol':'Use existing original Position and Heading torch bit0x80, retain other action flags and normal spell visibility bits; independent ordinary observer must see toggle.','acceptance':'Toggle, idle/heading/movement replication, persistence/re-entry, no input while typing/menu, no lobby ghost light, source bound and daylight/night visual check; key settings and spell/remote motion regressions.'})
 out=workspace/'PersonalTorchLab';out.mkdir(exist_ok=True);(out/'audit.json').write_text(json.dumps(result,indent=2));assert all(digest(Path(p))==h for p,h in inputs.items());return dict(passed=True,checks=len(checks),audit_only=True,normal_runtime_modified=False,report=str(out/'audit.json'))
